def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The three colored cells along the top define the starting points.
    seeds = [(0, c, grid[0][c]) for c in range(w) if grid[0][c] != 0]

    for sr, sc, color in seeds:
        targets = [
            (r, c) for r in range(h) for c in range(w)
            if grid[r][c] == color and (r, c) != (sr, sc)
        ]

        if targets:
            tr, tc = targets[0]
            for r in range(min(sr, tr), max(sr, tr) + 1):
                out[r][sc] = color
            for c in range(min(sc, tc), max(sc, tc) + 1):
                out[tr][c] = color
        else:
            for r in range(sr, h):
                out[r][sc] = color

    return out
